// ─────────────────────────────────────────────────────────────────────────────
// Live events sync — the app side of the "auto search" pipeline.
//
// Events shown in the feed come from two sources, fetched at launch and on
// pull-to-refresh, then merged:
//
//   1. SNAPSHOT — public/events-remote.json on GitHub. Regenerated by hand with
//      scripts/fetch-events.mjs (there is no cron anymore). Always works, no
//      key needed, cached 12h per device.
//   2. LIVE — the Ticketmaster Discovery API, queried straight from the
//      browser. Ticketmaster enables CORS on this API specifically so client
//      apps can use it, so no proxy is needed. Active only when
//      VITE_TICKETMASTER_API_KEY is set (free key: developer.ticketmaster.com
//      → "Create an app"). This is what keeps the feed fresh between snapshot
//      refreshes, so events never go stale waiting on a regen. Cached 1h.
//
// Live rows win on a title|city tie. Both sources are filtered to upcoming
// events only (see isUpcomingEvent) and deduped against each other AND against
// the bundled hand-written quests, so a live festival never doubles a curated
// one.
//
// Offline-first: every fetch never throws — on any failure the previous cached
// events (or an empty list) are returned, and the bundled quests always remain
// as the fallback floor.
// ─────────────────────────────────────────────────────────────────────────────
import { ALL_QUESTS, registerCustomQuests, type Quest } from '../data/quests'
import { isUpcomingEvent } from './game'

// The snapshot feed (see header above). Override in .env with VITE_EVENTS_URL
// to point at a fork or a local dev copy.
const EVENTS_URL =
  (import.meta.env.VITE_EVENTS_URL as string | undefined) ??
  'https://raw.githubusercontent.com/JacyFleisie/sidequest/main/public/events-remote.json'

// The live source (see header above). When unset, the snapshot alone is used.
const TICKETMASTER_URL = 'https://app.ticketmaster.com/discovery/v2/events.json'
const TICKETMASTER_KEY = import.meta.env.VITE_TICKETMASTER_API_KEY as string | undefined

const SNAPSHOT_CACHE_KEY = 'sidequest:remote-events-v1'
const LIVE_CACHE_KEY = 'sidequest:live-events-v1'
const SNAPSHOT_TTL_MS = 12 * 60 * 60 * 1000 // snapshot is static; a 12h cache is fine
const LIVE_TTL_MS = 60 * 60 * 1000 // live events: keep it fresh-ish without hammering the API
const MAX_EVENTS = 30

interface RemoteEventRow {
  id: string
  title: string
  emoji?: string
  category?: string
  city: string
  province: string
  provinceName?: string
  region?: string
  lat: number
  lng: number
  durationMin?: number
  cost?: number
  players?: [number, number]
  difficulty?: 1 | 2 | 3 | 4 | 5
  vibe?: string[]
  description: string
  completionLine?: string
  xp?: number
  when?: string
  startsAt?: string
  ticketInfo?: { required?: boolean; price?: string; where?: { label: string; url?: string }[]; url?: string }
  tags?: string[]
}

/** A single event as returned by the Ticketmaster Discovery API. */
interface TicketmasterEvent {
  name?: string
  url?: string
  info?: string
  pleaseNote?: string
  dates?: { start?: { local?: string; dateTime?: string } }
  priceRanges?: { min?: number }[]
  _embedded?: { venues?: { name?: string; city?: { name?: string } }[] }
}

const PROVINCE_NAMES: Record<string, string> = {
  GP: 'Gauteng', WC: 'Western Cape', KZN: 'KwaZulu-Natal', EC: 'Eastern Cape',
  FS: 'Free State', LP: 'Limpopo', MP: 'Mpumalanga', NW: 'North West', NC: 'Northern Cape',
}

