/** Venue-name hints that pin an event to a city before the fuzzy name match. */
const VENUE_HINTS: [RegExp, string][] = [
  [/time ?out market|grand ?arena|grandwest|cticc/i, 'Cape Town'],
  [/sunbet|time ?square|sun arena/i, 'Pretoria'],
  [/fnb stadium|ellis park|market theatre|goldrush dome|gold rush dome|the forum/i, 'Johannesburg'],
  [/the villa/i, 'Durban'],
  [/killarney/i, 'Cape Town'],
  [/kyalami/i, 'Midrand'],
  [/sun city/i, 'Rustenburg'],
  [/dhl stadium/i, 'Cape Town'],
]

const placeCity = (text: string | null | undefined): string | null => {
  if (!text) return null
  for (const [re, city] of VENUE_HINTS) if (re.test(text)) return city
  const lower = text.toLowerCase()
  for (const name of Object.keys(CITIES)) if (lower.includes(name)) return name
  return null
}

const cityInfo = (city: string): { city: string; province: string; lat: number; lng: number } | null => {
  const name = city.toLowerCase()
  const c = CITIES[name] ?? CITIES[Object.keys(CITIES).find((k) => name.includes(k)) ?? ''] ?? null
  if (!c) return null
  return { city: name, ...c }
}

const slug = (s: string): string => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50)
const whenLabel = (d: Date): string =>
  d.toLocaleDateString('en-ZA', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' })
const fmt = new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR', maximumFractionDigits: 0 })

// ── Transforms ───────────────────────────────────────────────────────────────

/** Shapes a snapshot feed row into a playable Quest. Unknown fields fall back to safe defaults. */
const rowToQuest = (r: RemoteEventRow): Quest => ({
  id: r.id,
  title: r.title,
  emoji: r.emoji ?? '🎟️',
  category: (r.category as Quest['category']) ?? 'event',
  province: (r.province as Quest['province']) ?? 'GP',
  provinceName: r.provinceName ?? PROVINCE_NAMES[r.province] ?? 'South Africa',
  city: r.city ?? 'South Africa',
  region: r.region ?? '',
  lat: r.lat,
  lng: r.lng,
  durationMin: r.durationMin ?? 150,
  cost: r.cost ?? 0,
  players: r.players ?? [1, 8],
  difficulty: r.difficulty ?? 1,
  vibe: (r.vibe as Quest['vibe']) ?? ['entertainment'],
  description: r.description,
  completionLine: r.completionLine ?? 'You were there. Legend.',
  xp: r.xp ?? 300,
  when: r.when,
  startsAt: r.startsAt,
  ticketInfo: r.ticketInfo,
  tags: r.tags ?? ['live'],
})

/**
 * Shapes a raw Ticketmaster event into a playable Quest.
 * Returns null when the event is in the past or can't be pinned to a known
 * SA city — we never show an event we can't place accurately.
 */
export const liveEventToQuest = (ev: TicketmasterEvent, now: Date): Quest | null => {
  const venue = ev._embedded?.venues?.[0]
  const startRaw = ev.dates?.start?.local ?? ev.dates?.start?.dateTime
  const start = startRaw ? new Date(startRaw) : null
  if (!start || Number.isNaN(start.getTime())) return null
  if (start.getTime() < now.getTime() - 86_400_000) return null // drop past events

  const info = cityInfo(venue?.city?.name ?? placeCity(venue?.name) ?? '')
  if (!info) return null // never pin an event we can't place accurately

  const minPrice = ev.priceRanges?.[0]?.min
  const priceLabel = typeof minPrice === 'number' ? `from ${fmt.format(Math.round(minPrice))}` : 'prices vary'
  return {
    // The `remote-` prefix is the app-wide contract for "auto-discovered live
    // event" (map pins, the Live feed filter) — keep it for live rows too.
    id: `remote-ticketmaster-${slug(ev.name ?? '')}-${start.getFullYear()}${String(start.getMonth() + 1).padStart(2, '0')}${String(start.getDate()).padStart(2, '0')}`,
    title: ev.name ?? 'Untitled event',
    emoji: '🎟️',
    category: 'event',
    city: info.city,
    province: info.province as Quest['province'],
    provinceName: PROVINCE_NAMES[info.province],
    region: '',
    lat: info.lat,
    lng: info.lng,
    durationMin: 150,
    cost: 0,
    players: [1, 8],
    difficulty: 1,
    vibe: ['entertainment'],
    description:
      ev.info?.slice(0, 240) ||
      'A live ticketed event in South Africa — grab your tickets on Ticketmaster.',
    completionLine: 'You were there. Legend.',
    xp: 300,
    when: whenLabel(start),
    startsAt: start.toISOString(),
    ticketInfo: {
      required: true,
      price: priceLabel,
      where: [{ label: 'Online at Ticketmaster', url: ev.url }],
    },
    tags: ['ticketmaster', 'live', info.city.replace(/\s+/g, '-')],
  }
}

/**
 * Merges the snapshot and live feeds into one deduped, upcoming-only list.
 * Live rows win on a title|city tie. Bundled hand-written quests are never
 * duplicated. Sorted by start date, capped at MAX_EVENTS.
 */
export const mergeEventSources = (snapshot: Quest[], live: Quest[]): Quest[] => {
  const bundledTitles = new Set(ALL_QUESTS.map((q) => q.title.toLowerCase()))
  const seen = new Set<string>()
  const out: Quest[] = []
  for (const q of [...live, ...snapshot]) {
    if (bundledTitles.has(q.title.toLowerCase())) continue
    const key = `${q.title.toLowerCase()}|${q.city.toLowerCase()}`
    if (seen.has(key)) continue
    seen.add(key)
    out.push(q)
  }
  return out
    .filter(isUpcomingEvent)
    .sort((a, b) => (a.startsAt ?? '').localeCompare(b.startsAt ?? ''))
    .slice(0, MAX_EVENTS)
}

// ── Caching ──────────────────────────────────────────────────────────────────

const readCache = (key: string, ttlMs: number): Quest[] | null => {
  try {
    const raw = localStorage.getItem(key)
    if (!raw) return null
    const { at, events } = JSON.parse(raw) as { at: number; events: Quest[] }
    if (Date.now() - at > ttlMs) return null
    return events
  } catch {
    return null
  }
}

const writeCache = (key: string, events: Quest[]) => {
  try {
    localStorage.setItem(key, JSON.stringify({ at: Date.now(), events }))
  } catch {
    // storage full/blocked — the feed just fetches again next launch
  }
}

// ── Fetching ─────────────────────────────────────────────────────────────────

/** Fetches the static snapshot feed (cached SNAPSHOT_TTL_MS). Never throws. */
async function fetchSnapshot(force = false): Promise<Quest[]> {
  const cached = readCache(SNAPSHOT_CACHE_KEY, SNAPSHOT_TTL_MS)
  if (cached && !force) return cached
  try {
    const res = await fetch(EVENTS_URL, { signal: AbortSignal.timeout(10_000) })
    if (!res.ok) return cached ?? []
    const data = (await res.json()) as { events?: RemoteEventRow[] }
    const events = (data.events ?? []).map(rowToQuest)
    if (events.length > 0) writeCache(SNAPSHOT_CACHE_KEY, events)
    return events.length > 0 ? events : (cached ?? [])
  } catch {
    return cached ?? []
  }
}

/**
 * Queries the Ticketmaster Discovery API for upcoming ZA events (cached
 * LIVE_TTL_MS). No-ops when VITE_TICKETMASTER_API_KEY is unset. Never throws —
 * a failure falls back to the cached live list, then to nothing.
 */
async function fetchLiveEvents(force = false): Promise<Quest[]> {
  if (!TICKETMASTER_KEY) return []
  const cached = readCache(LIVE_CACHE_KEY, LIVE_TTL_MS)
  if (cached && !force) return cached
  try {
    const params = new URLSearchParams({
      apikey: TICKETMASTER_KEY,
      countryCode: 'ZA',
      sort: 'date,asc',
      size: '100',
      includeTBA: 'no',
      includeTBD: 'no',
    })
    const res = await fetch(`${TICKETMASTER_URL}?${params}`, { signal: AbortSignal.timeout(10_000) })
    if (!res.ok) return cached ?? []
    const data = (await res.json()) as { _embedded?: { events?: TicketmasterEvent[] } }
    const events = (data._embedded?.events ?? [])
      .map((ev) => liveEventToQuest(ev, new Date()))
      .filter((q): q is Quest => q !== null)
    if (events.length > 0) writeCache(LIVE_CACHE_KEY, events)
    return events.length > 0 ? events : (cached ?? [])
  } catch {
    return cached ?? []
  }
}

/** Fetches the merged snapshot + live events feed. Never throws — returns [] offline. */
export async function fetchRemoteEvents(force = false): Promise<Quest[]> {
  const [snapshot, live] = await Promise.all([fetchSnapshot(force), fetchLiveEvents(force)])
  return mergeEventSources(snapshot, live)
}

/** Fetches + registers live events app-wide so quest sheets resolve them, then
 * tells the feed to re-render. Fire-and-forget from App boot and feed refresh. */
export async function syncRemoteEvents(force = false): Promise<Quest[]> {
  const events = await fetchRemoteEvents(force)
  if (events.length > 0) {
    registerCustomQuests(events)
    window.dispatchEvent(new CustomEvent('sidequest:remote-events'))
  }
  return events
}
